const navNames = { overview:'Обзор', equipment:'Оборудование', components:'Комплектующие', history:'История', audits:'Инвентаризации', directories:'Сотрудники', locations:'Структура локаций', catalogs:'Справочники', import:'Импорт данных' };
const roleInfo = () => currentRole === 'manager' ? manager : employees[0];
const molFor = id => employees.find(person => person.id === id) || employees[0];
const assetFor = id => db.assets.find(asset => asset.id === id);
const locFor = asset => locations[asset.location] || locations[0];
const canEdit = asset => currentRole === 'manager' || asset?.mol === roleInfo().id;
const isManager = () => currentRole === 'manager';
const persist = () => localStorage.setItem('velvetInventoryDemo', JSON.stringify(db));
const safe = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const initialOf = name => String(name || '??').split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toLocaleUpperCase('ru');
const currentDate = () => new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric'}).format(new Date());
const fmtDate = date => date ? new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric'}).format(new Date(`${date}T12:00:00`)) : '—';
const statusTone = value => value === 'Исправно' || value === 'Используется' || value === 'Завершена' ? 'green' : value === 'Неисправно' || value === 'Выведено из эксплуатации' ? 'red' : value === 'В ремонте' || value === 'В резерве' || value === 'В процессе' ? 'amber' : value === 'Запланирована' ? 'blue' : '';
const badge = value => `<span class="tag ${statusTone(value)}">${safe(value)}</span>`;
const fullLocation = asset => { const loc=locFor(asset); return `${loc.quarter} · ${loc.участок} · ${loc.building} · ${loc.section} · ${asset.roomOverride || loc.room}`; };
const assetIcon = type => ['Монитор','Ноутбук','Системный блок','Серверное оборудование','Сетевое оборудование','Принтер','ИБП'].includes(type) ? ({'Монитор':'monitor','Ноутбук':'laptop','Системный блок':'monitor','Серверное оборудование':'box','Сетевое оборудование':'router','Принтер':'printer','ИБП':'box'}[type]) : 'box';
const assetCell = asset => `<div class="asset-main"><span class="asset-thumb">${icon(assetIcon(asset.type))}</span><span class="asset-title"><strong>${safe(asset.name)}</strong><small>${safe(asset.inventory)} · ${safe(asset.type)}</small></span></div>`;
const rowHTML = asset => `<tr data-action="open-asset" data-id="${safe(asset.id)}"><td>${assetCell(asset)}</td><td>${safe(asset.maker)} <span class="subtext">·</span> ${safe(asset.model)}</td><td>${safe(locFor(asset).quarter.replace(' квартал',''))}<small class="subtext" style="display:block;margin-top:4px">${safe(asset.roomOverride || locFor(asset).room)}</small></td><td>${badge(asset.condition)}</td><td>${badge(asset.status)}</td><td>${safe(molFor(asset.mol).name)}</td><td>${safe(asset.updated)}</td><td><button class="row-more" data-action="open-asset" data-id="${safe(asset.id)}" aria-label="Открыть карточку">${icon('more')}</button></td></tr>`;

function setRole(role) {
  closeDetail();
  currentRole = role;
  localStorage.setItem('velvetInventoryRole', role);
  $('.role-switch').classList.remove('open');
  $('#profile-button').setAttribute('aria-expanded','false');
  if (!isManager() && ['directories','locations','catalogs','import'].includes(currentView)) currentView = 'overview';
  render();
  toast(role === 'manager' ? 'Открыт профиль руководства' : 'Открыт профиль МОЛ');
}
function renderProfile() {
  const user = roleInfo();
  $('#profile-avatar').textContent = user.initials;
  $('#profile-name').textContent = user.name;
  $('#profile-role').textContent = currentRole === 'manager' ? 'Руководство' : 'МОЛ · ИТ-отдел';
  $('#check-mol').textContent = currentRole === 'mol' ? '✓' : '';
  $('#check-manager').textContent = currentRole === 'manager' ? '✓' : '';
  $('#mobile-role-label').textContent = currentRole === 'manager' ? 'Вы вошли как руководство' : 'Вы вошли как МОЛ';
  $$('.manager-nav').forEach(item => item.style.display = isManager() ? 'flex' : 'none');
  $('#nav-equipment-count').textContent = String(db.assets.length);
}
function render() {
  renderProfile();
  $$('.nav-link').forEach(item => item.classList.toggle('active', item.dataset.view === currentView));
  const breadcrumbTitle=$('#breadcrumb-title'); if(breadcrumbTitle) breadcrumbTitle.textContent = navNames[currentView] || 'Обзор';
  const renderers = { overview:renderOverview, equipment:renderEquipment, components:renderComponents, history:renderHistory, audits:renderAudits, directories:renderDirectories, locations:renderLocations, catalogs:renderCatalogs, import:renderImport };
  $('#content').innerHTML = (renderers[currentView] || renderOverview)();
  bindContent();
  $('#footer-year').textContent = currentYear;
  closeSidebar();
}

function heading(title, subtitle, actions = '') { return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`; }
function statCard(label,value,detail,kind='box',tone='') { return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${tone}">${icon(kind)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${detail}</div></article>`; }
function visibleAssets() { return db.assets; }
function renderOverview() {
  const own=visibleAssets().filter(a=>isManager()||a.mol===roleInfo().id);
  return `${heading('Рабочий стол', `Добро пожаловать, ${safe(roleInfo().name)}`, `<button class="btn btn-primary" data-action="add-asset">${icon('plus')}Добавить оборудование</button>`)}
    <section class="welcome-links"><button class="welcome-link" data-view="equipment"><strong>Оборудование</strong><span>${isManager()?'Открыть общий реестр':`Мое оборудование · ${own.length} единиц`}</span></button><button class="welcome-link" data-view="components"><strong>Комплектующие</strong><span>Реестр и установка компонентов</span></button><button class="welcome-link" data-view="audits"><strong>Инвентаризации</strong><span>${isManager()?'Проверки всех ответственных':`Мои проверки · ${db.audits.filter(a=>a.owner===roleInfo().name).length}`}</span></button><button class="welcome-link" data-view="history"><strong>История изменений</strong><span>Перемещения и действия в системе</span></button>${isManager()?'<button class="welcome-link" data-view="directories"><strong>Сотрудники</strong><span>Сотрудники и учетные записи</span></button>':''}</section>`;
}

function filteredAssets() {
  let list=visibleAssets();
  if(filters.status) list=list.filter(a=>a.status===filters.status);
  if(filters.type) list=list.filter(a=>a.type===filters.type);
  if(filters.quarter!=='' && filters.quarter!==null) list=list.filter(a=>String(a.location)===String(filters.quarter));
  if(filters.mol) list=list.filter(a=>a.mol===filters.mol);
  const query=inventoryQuery.toLocaleLowerCase('ru');
  if(query) list=list.filter(a=>[a.inventory,a.name,a.accounting,a.serial,a.type,a.model,a.maker,molFor(a.mol).name,fullLocation(a)].join(' ').toLocaleLowerCase('ru').includes(query));
  return list;
}
function renderEquipment() {
  const list=filteredAssets();
  const types=[...new Set(db.assets.map(a=>a.type))].sort((a,b)=>a.localeCompare(b,'ru'));
  const actions=`${isManager()?`<button class="btn" data-action="export">${icon('download')}<span>Экспорт</span></button>`:''}<button class="btn btn-primary" data-action="add-asset">${icon('plus')}<span>Добавить оборудование</span></button>`;
  return `${heading('Оборудование',`${isManager()?'Реестр оборудования города-отеля':'Просмотр всего реестра · изменение закрепленных единиц'} · ${db.assets.length} единиц`,actions)}
    <div class="page-tools"><label class="search-control">${icon('search')}<input class="input-control" id="equipment-search" value="${safe(inventoryQuery)}" placeholder="Инвентарный номер, название или серийный номер"></label><select class="select-control" id="equipment-quarter"><option value="">Все кварталы</option>${locations.map((loc,i)=>`<option value="${i}" ${filters.quarter===String(i)?'selected':''}>${loc.quarter}</option>`).join('')}</select><select class="select-control" id="equipment-status"><option value="">Все статусы</option>${['Используется','В резерве','В ремонте','Неизвестно','Выведено из эксплуатации'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select><select class="select-control" id="equipment-mol"><option value="">Все МОЛ</option>${employees.filter(e=>e.role==='МОЛ').map(e=>`<option value="${e.id}" ${filters.mol===e.id?'selected':''}>${safe(e.name)}</option>`).join('')}</select><button class="btn" data-action="reset-filters">${icon('filter')}<span>Сбросить</span></button></div>
    <div class="filter-row"><button class="filter-chip ${!filters.type?'selected':''}" data-filter-type="">Все типы</button>${types.map(type=>`<button class="filter-chip ${filters.type===type?'selected':''}" data-filter-type="${safe(type)}">${safe(type)}</button>`).join('')}</div>
    <div class="results-bar"><span>Найдено: <strong>${list.length}</strong> ${plural(list.length,'единица','единицы','единиц')}</span><span>Сортировка: <strong>по актуализации</strong> ${icon('chevron-down')}</span></div>
    <article class="card table-card"><div class="table-scroll"><table class="data-table"><thead><tr><th>Оборудование</th><th>Производитель и модель</th><th>Локация</th><th>Состояние</th><th>Статус</th><th>МОЛ</th><th>Обновлено</th><th></th></tr></thead><tbody>${list.map(rowHTML).join('')||`<tr><td colspan="8"><div class="empty-state"><strong>Ничего не найдено</strong><span>Измените условия фильтра или поисковый запрос</span></div></td></tr>`}</tbody></table></div><div class="table-footer"><span>Показаны ${list.length} из ${visibleAssets().length} единиц оборудования</span><div class="pagination"><button class="page-num active">1</button><button class="page-num">2</button><button class="page-num">${icon('chevron')}</button></div></div></article>`;
}
