  const rows=sets[catalogTab].map(([name,count],i)=>`<tr><td><strong class="strong">${safe(name)}</strong></td><td>${catalogTab==='types'?i>2?'Оборудование и периферия':'ИТ-оборудование':'—'}</td><td>${count}</td><td>${badge('Активен')}</td><td><button class="row-more" data-action="edit-catalog" data-value="${safe(name)}">${icon('more')}</button></td></tr>`).join('');
