function renderImport() {
  return `${heading('Импорт данных','Загрузка оборудования из файла Excel или CSV',`<button class="btn" data-action="download-template">${icon('download')}Шаблон файла</button>`)}<div class="module-grid"><article class="card"><header class="card-head"><div><h2>Загрузить файл</h2><p>Поддерживаемые форматы: .xlsx, .xls, .csv</p></div><span class="module-icon">${icon('upload')}</span></header><label class="upload-zone" id="upload-zone"><input type="file" id="file-input" accept=".xlsx,.xls,.csv"><span class="upload-icon">${icon('upload')}</span><strong class="upload-default">Перетащите файл сюда или выберите его</strong><strong class="upload-filename" id="upload-filename"></strong><span class="upload-default">Максимальный размер файла — 20 МБ</span><span class="btn btn-soft upload-default">Выбрать файл</span></label><div class="import-steps"><span class="import-step"><i class="step-number">1</i><span><strong>Загрузка</strong>Форматирование файла</span></span><span class="import-step"><i class="step-number">2</i><span><strong>Сопоставление</strong>Колонки и поля</span></span><span class="import-step"><i class="step-number">3</i><span><strong>Проверка</strong>Результат до записи</span></span></div><div style="padding:0 18px 18px"><button class="btn btn-primary" style="width:100%" id="import-continue" disabled data-action="import-continue">Продолжить</button></div></article><article class="card"><header class="card-head"><div><h2>Поля реестра</h2><p>Данные для создания карточки оборудования</p></div></header><div class="status-rows">${['Участок, корпус и секция','Тип и модель оборудования','Бухгалтерское наименование','Инвентарный номер и S/N','Дефект и примечания','Пользователь и МОЛ','Дата актуализации'].map((x,i)=>`<div class="status-row"><span class="status-row-value">${String(i+1).padStart(2,'0')}</span><span class="status-row-label">${x}</span>${i===3?badge('Обязательно'):''}</div>`).join('')}</div><div class="table-footer">${icon('alert')} Дубликаты инвентарных номеров проверяются до импорта</div></article></div><article class="card" style="margin-top:15px"><header class="card-head"><div><h2>История загрузок</h2><p>Последние операции импорта</p></div></header><div class="table-scroll"><table class="data-table"><thead><tr><th>Файл</th><th>Дата</th><th>Загружено строк</th><th>Ошибки</th><th>Статус</th></tr></thead><tbody><tr><td>Сведения об оборудовании.csv</td><td>2 ноября 2026</td><td>24</td><td>2</td><td>${badge('Завершена')}</td></tr></tbody></table></div></article>`;
}
function plural(count, one, few, many) { const n=Math.abs(count)%100, n1=n%10; if(n>10&&n<20)return many; if(n1>1&&n1<5)return few; if(n1===1)return one; return many; }

function bindContent() {
  const directoryTabs=$$('.section-tabs .section-tab',$('#content'));
  if(directoryTabs.length===3){directoryTabs[1].addEventListener('click',()=>document.querySelector('[data-action="manage-accounts"]')?.click());directoryTabs[2].addEventListener('click',()=>openModal('Подразделения и должности','Организационная структура',`<div class="module-grid"><article class="module-card"><div class="module-card-head"><h2>Подразделения</h2><span class="tag green">Активны</span></div><p>ИТ-отдел<br>Администрация</p></article><article class="module-card"><div class="module-card-head"><h2>Должности</h2><span class="tag green">Активны</span></div><p>Системный администратор<br>Инженер<br>Специалист технической поддержки<br>Руководитель</p></article></div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal">Закрыть</button></div>`));}
  const overviewFilter=$('#overview-quarter'); if(overviewFilter) overviewFilter.addEventListener('change',e=>{overviewQuarter=e.target.value;render();});
  const search=$('#equipment-search'); if(search) search.addEventListener('input',e=>{inventoryQuery=e.target.value;renderEquipmentKeepFocus(e.target.selectionStart);});
  const quarter=$('#equipment-quarter'); if(quarter) quarter.addEventListener('change',e=>{filters.quarter=e.target.value;render();});
  const status=$('#equipment-status'); if(status) status.addEventListener('change',e=>{filters.status=e.target.value;render();});
  const mol=$('#equipment-mol'); if(mol) mol.addEventListener('change',e=>{filters.mol=e.target.value;render();});
  const historySearch=$('#history-search'); if(historySearch) historySearch.addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase('ru'); $$('tbody tr',$('#content')).forEach(row=>row.style.display=row.textContent.toLocaleLowerCase('ru').includes(q)?'':'none');});
  const historyAsset=$('#history-asset'); if(historyAsset) historyAsset.addEventListener('change',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=!e.target.value||row.dataset.id===e.target.value?'':'none');});
  const historyMol=$('#history-mol'); if(historyMol) historyMol.addEventListener('change',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=!e.target.value||row.textContent.includes(molFor(e.target.value).name)?'':'none');});
  const historyType=$('#history-type'); if(historyType) historyType.addEventListener('change',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=!e.target.value||row.querySelector('.tag')?.textContent===e.target.value?'':'none');});
  const componentSearch=$('#component-search'); if(componentSearch) componentSearch.addEventListener('input',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=row.textContent.toLocaleLowerCase('ru').includes(e.target.value.toLocaleLowerCase('ru'))?'':'none');});
  const componentMol=$('#component-mol'); if(componentMol) componentMol.addEventListener('change',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=!e.target.value||row.textContent.includes(molFor(e.target.value).name)?'':'none');});
  const employeeSearch=$('#employee-search'); if(employeeSearch) employeeSearch.addEventListener('input',e=>{$$('tbody tr',$('#content')).forEach(row=>row.style.display=row.textContent.toLocaleLowerCase('ru').includes(e.target.value.toLocaleLowerCase('ru'))?'':'none');});
  const file=$('#file-input'); if(file) file.addEventListener('change',()=>{if(file.files?.[0]){$('#upload-zone').classList.add('has-file');$('#upload-filename').textContent=file.files[0].name;$('#import-continue').disabled=false;}});
}
function renderEquipmentKeepFocus(position) { const value=inventoryQuery; $('#content').innerHTML=renderEquipment(); bindContent(); const search=$('#equipment-search'); search.focus(); search.setSelectionRange(position,position); }
function openAsset(id) {
  const asset=assetFor(id); if(!asset) return;
  const location=locFor(asset); const mol=molFor(asset.mol); const editable=canEdit(asset);
  const components=db.components.filter(c=>c.parent===asset.id&&c.current);
  const events=db.events.filter(e=>e.asset===asset.id).slice(0,4);
  $('#detail-drawer').innerHTML=`<div class="drawer-top"><span class="drawer-top-label">Карточка оборудования</span><span class="drawer-actions">${editable?`<button class="btn btn-small" data-action="edit-asset" data-id="${asset.id}">${icon('edit')}Изменить</button>`:''}<button class="icon-button" data-action="close-detail" aria-label="Закрыть">${icon('close')}</button></span></div><div class="drawer-hero"><div class="drawer-asset-head"><span class="drawer-asset-icon">${icon(assetIcon(asset.type))}</span><span class="drawer-asset-title"><h2>${safe(asset.name)}</h2><p>${safe(asset.type)} · ${safe(asset.maker)} ${safe(asset.model)}</p></span></div><div class="drawer-id">Инвентарный номер <strong>${safe(asset.inventory)}</strong></div><div class="drawer-tags">${badge(asset.condition)}${badge(asset.status)}</div></div><div class="drawer-content"><section class="drawer-section"><header class="drawer-section-head"><h3>Основные сведения</h3><button class="btn-text" data-action="copy-inventory" data-value="${safe(asset.inventory)}">Копировать номер</button></header><div class="kv-grid"><div class="kv"><label>Бухгалтерское название</label><strong>${safe(asset.accounting||'Не указано')}</strong></div><div class="kv"><label>Серийный номер</label><strong>${safe(asset.serial||'Не указан')}</strong></div><div class="kv"><label>Производитель</label><strong>${safe(asset.maker)}</strong></div><div class="kv"><label>Модель</label><strong>${safe(asset.model)}</strong></div><div class="kv"><label>Дата поступления</label><strong>${safe(fmtDate(asset.date))}</strong></div><div class="kv"><label>Актуализация</label><strong>${safe(asset.updated)}</strong></div></div></section><section class="drawer-section"><header class="drawer-section-head"><h3>Местонахождение и назначение</h3>${editable?`<button class="btn-text" data-action="move-asset" data-id="${asset.id}">Изменить</button>`:''}</header><div class="kv-grid"><div class="kv" style="grid-column:1/-1"><label>Физическое местонахождение</label><strong class="location-path">${safe(location.quarter)} ${icon('chevron')}${safe(location.участок)} ${icon('chevron')}${safe(location.building)} ${icon('chevron')}${safe(location.section)} ${icon('chevron')}${safe(asset.roomOverride||location.room)}</strong></div><div class="kv"><label>Адрес</label><strong>${safe(location.address)}</strong></div><div class="kv"><label>Назначено</label><strong>${safe(asset.assigned||'Не назначено')}</strong></div><div class="kv"><label>Материально ответственное лицо</label><strong>${safe(mol.name)}</strong></div><div class="kv"><label>Подразделение</label><strong>${safe(mol.department)}</strong></div></div></section><section class="drawer-section"><header class="drawer-section-head"><h3>Техническое состояние</h3>${editable?`<button class="btn-text" data-action="change-status" data-id="${asset.id}">Изменить статус</button>`:''}</header><div class="kv-grid"><div class="kv"><label>Техническое состояние</label><strong>${safe(asset.condition)}</strong></div><div class="kv"><label>Статус использования</label><strong>${safe(asset.status)}</strong></div><div class="kv" style="grid-column:1/-1"><label>Описание дефекта</label><strong>${safe(asset.defect||'Нет замечаний')}</strong></div><div class="kv" style="grid-column:1/-1"><label>Примечание</label><strong>${safe(asset.note||'—')}</strong></div></div></section><section class="drawer-section"><header class="drawer-section-head"><h3>Установленные комплектующие (${components.length})</h3>${editable?`<button class="btn-text" data-action="install-component" data-id="${asset.id}">${icon('plus')}Установить</button>`:''}</header>${components.length?components.map(c=>`<div class="component-item"><span class="asset-thumb">${icon('layers')}</span><span class="component-item-copy"><strong>${safe(c.name)}</strong><span>${safe(c.inventory)} · ${safe(c.role)} · с ${safe(fmtDate(c.installed))}</span></span>${editable?`<button class="row-more" data-action="remove-component" data-id="${c.id}" aria-label="Снять компонент">${icon('more')}</button>`:''}</div>`).join(''):`<div class="empty-inline">Установленных комплектующих нет</div>`}</section><section class="drawer-section"><header class="drawer-section-head"><h3>История изменений</h3><button class="btn-text" data-view="history">Весь журнал ${icon('arrow')}</button></header>${events.length?`<div class="timeline">${events.map(e=>`<div class="timeline-entry"><strong>${safe(e.title)}</strong><span>${safe(e.date)} · ${safe(e.actor)}</span></div>`).join('')}</div>`:`<div class="empty-inline">Событий пока нет</div>`}</section>${editable?`<div class="drawer-actions" style="justify-content:flex-start;flex-wrap:wrap;padding-top:3px"><button class="btn btn-soft btn-small" data-action="move-asset" data-id="${asset.id}">${icon('pin')}Переместить</button><button class="btn btn-small" data-action="change-mol" data-id="${asset.id}">${icon('users')}Изменить МОЛ</button><button class="btn btn-danger btn-small" data-action="retire-asset" data-id="${asset.id}">Списать</button></div>`:`<div class="inline-note">${icon('alert')}Изменение записи доступно только ответственному МОЛ или руководству.</div>`}</div>`;
  $$('.kv',$('#detail-drawer')).find(el=>el.querySelector('label')?.textContent==='Адрес')?.remove();
  $('#detail-panel').classList.add('open'); $('#detail-panel').setAttribute('aria-hidden','false');
}
function openComponent(id) { const comp=db.components.find(c=>c.id===id); if(!comp)return; if(comp.parent)openAsset(comp.parent); else openInstallFreeComponent(comp); }
function openInstallFreeComponent(comp) { const available=visibleAssets().filter(asset=>canEdit(asset)); openModal(comp.name,'Свободная комплектующая',`<p class="modal-info">${safe(comp.inventory)} · ${safe(comp.type)} · ${safe(comp.maker)}. Выберите устройство для установки.</p><form data-form="install-free-component" data-id="${comp.id}"><div class="form-grid">${field('Родительское устройство','parent',available[0]?.id||'','required',true,available.map(a=>({value:a.id,label:`${a.name} · ${a.inventory}`})))}${field('Роль в составе','role','','text',false,null,'Например, накопитель')}${field('Дата установки','date',new Date().toISOString().slice(0,10),'date',false)}${field('Примечание','note','','text',true,null,'')}</div>${modalFooter('Установить')}</form>`); }
function closeDetail() { $('#detail-panel').classList.remove('open'); $('#detail-panel').setAttribute('aria-hidden','true'); }
function openModal(title,eyebrow,body) { $('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=body;$('#modal-layer').classList.add('open');$('#modal-layer').setAttribute('aria-hidden','false'); setTimeout(()=>$('#modal-body input, #modal-body select, #modal-body textarea')?.focus(),30); }
function closeModal() { $('#modal-layer').classList.remove('open');$('#modal-layer').setAttribute('aria-hidden','true'); }
function field(label,name,value='',type='text',wide=false,options=null,placeholder='') { const required=type==='required'; const input=options?`<select name="${name}" ${required?'required':''}>${options.map(opt=>typeof opt==='string'?`<option ${opt===value?'selected':''}>${safe(opt)}</option>`:`<option value="${safe(opt.value)}" ${opt.value===value?'selected':''}>${safe(opt.label)}</option>`).join('')}</select>`:`<input name="${name}" type="${required?'text':type}" value="${safe(value)}" placeholder="${safe(placeholder)}" ${required?'required':''}>`; return `<div class="form-field ${wide?'wide':''}"><label>${label}</label>${input}</div>`; }
function modalFooter(label='Сохранить') { return `<div class="form-footer"><button type="button" class="btn" data-action="close-modal">Отмена</button><button type="submit" class="btn btn-primary">${label}</button></div>`; }
function openAddAsset() {
  if(!isManager() && !roleInfo()) return;
  const types=['Системный блок','Монитор','Ноутбук','Сетевое оборудование','Серверное оборудование','Периферийное устройство','Принтер','ИБП','Мобильное устройство'];
  const assignmentOptions=[...employees.map(e=>({value:`employee:${e.id}`,label:`Сотрудник · ${e.name}`})),...locations.map((l,i)=>({value:`location:${i}`,label:`Локация · ${l.quarter} · ${l.room}`}))];
  const molField=isManager()?field('Материально ответственное лицо','mol',employees[0].id,'required',false,employees.filter(e=>e.role==='МОЛ').map(e=>({value:e.id,label:e.name}))):`<div class="form-field"><label>Материально ответственное лицо</label><input value="${safe(roleInfo().name)}" disabled><input type="hidden" name="mol" value="${safe(roleInfo().id)}"></div>`;
  openModal('Добавить оборудование','Новая карточка',`<form id="asset-form" data-form="asset"><div class="form-grid">${field('Реальное название','name','','required',true,null,'Например, монитор Dell P2422H')}${field('Инвентарный номер','inventory','','required',false,null,'VS-IT-000/24')}<div class="form-field"><label>Тип оборудования</label><div class="inline-control"><select name="type" required>${types.map(t=>`<option>${t}</option>`).join('')}</select><button type="button" class="btn btn-small" data-action="inline-type">Добавить</button></div></div>${field('Производитель','maker','')}${field('Модель','model','')}${field('Бухгалтерское название','accounting','','text',true)}${field('Серийный номер','serial')}
    <div class="form-field wide"><label>Физическое местонахождение</label><div class="inline-control"><select name="location" required>${locations.map((l,i)=>`<option value="${i}">${safe(`${l.quarter} · ${l.участок} · ${l.building} · ${l.section} · ${l.room}`)}</option>`).join('')}</select><button type="button" class="btn btn-small" data-action="inline-location">Добавить</button></div></div>
    <div class="form-field wide"><label>Назначение: сотрудник или локация</label><div class="inline-control"><select name="assigned">${assignmentOptions.map(o=>`<option value="${safe(o.value)}">${safe(o.label)}</option>`).join('')}<option value="">Не назначено</option></select><button type="button" class="btn btn-small" data-action="inline-employee">Добавить сотрудника</button></div></div>${molField}${field('Техническое состояние','condition','Неизвестно','required',false,['Неизвестно','Исправно','Неисправно'])}${field('Статус использования','status','Неизвестно','required',false,['Неизвестно','Используется','В резерве','В ремонте','Выведено из эксплуатации'])}${field('Описание дефекта','defect','','text',true)}${field('Примечание','note','','text',true)}</div>${modalFooter('Создать карточку')}</form>`);
}
function openEditAsset(id) {
  const asset=assetFor(id); if(!asset||!canEdit(asset)){toast('Нет прав на изменение этой записи');return;}
  openModal('Изменить оборудование','Карточка оборудования',`<form id="asset-form" data-form="edit-asset" data-id="${asset.id}"><div class="form-grid">${field('Реальное название','name',asset.name,'required',true)}${field('Инвентарный номер','inventory',asset.inventory,'text',false,null,'Не изменяется')}${field('Тип оборудования','type',asset.type,'required',false,['Системный блок','Монитор','Ноутбук','Сетевое оборудование','Серверное оборудование','Периферийное устройство','Принтер','ИБП','Мобильное устройство'])}${field('Производитель','maker',asset.maker)}${field('Модель','model',asset.model)}${field('Бухгалтерское название','accounting',asset.accounting,'text',true)}${field('Серийный номер','serial',asset.serial)}${field('Примечание','note',asset.note,'text',true)}</div>${modalFooter()}</form>`);
}
function openActionForm(action,id) {
  const component=action==='remove-component'?db.components.find(c=>c.id===id):null;
  const asset=assetFor(action==='remove-component'?component?.parent:id);if(action!=='add-component'&&(!asset||!canEdit(asset))){toast('Нет прав на изменение этой записи');return;}
  const molOpts=employees.map(e=>({value:e.id,label:e.name})); let title='', fields='', submit='Сохранить изменения', eyebrow='Оборудование';
  if(action==='change-status'){title='Изменить состояние';fields=field('Техническое состояние','condition',asset.condition,'required',false,['Неизвестно','Исправно','Неисправно'])+field('Статус использования','status',asset.status,'required',false,['Неизвестно','Используется','В резерве','В ремонте','Выведено из эксплуатации'])+field('Описание дефекта','defect',asset.defect,'text',true,null,'Опишите неисправность или оставьте пустым')+field('Причина изменения','reason','','text',true,null,'');}
  if(action==='move-asset'){title='Переместить оборудование';fields=field('Новое физическое местонахождение','location',String(asset.location),'required',true,locations.map((x,i)=>({value:String(i),label:`${x.quarter} · ${x.building}`})))+field('Помещение','room',asset.roomOverride||locFor(asset).room,'required',false,null,'Кабинет, склад, серверная')+field('Назначение','assigned',asset.assigned,'text',false,null,'Сотрудник или локация')+field('Причина перемещения','reason','','text',true,null,'');submit='Зафиксировать перемещение';}
  if(action==='change-mol'){title='Передать ответственность';fields=field('Новый МОЛ','mol',asset.mol,'required',true,molOpts)+field('Основание передачи','reason','','text',true,null,'');submit='Изменить МОЛ';}
  if(action==='retire-asset'){title='Списать оборудование';eyebrow='Вывод из эксплуатации';fields=`<p class="modal-info">Оборудование останется в реестре и истории. Списанные единицы можно найти фильтром по статусу.</p>${field('Дата списания','date',new Date().toISOString().slice(0,10),'date',false)}${field('Причина списания','reason','','text',true,null,'Укажите причину')}`;submit='Подтвердить списание';}
  if(action==='install-component'){const available=db.components.filter(c=>!c.current&&c.id!==id);title='Установить комплектующую';fields=available.length?field('Компонент','component',available[0]?.id,'required',true,available.map(c=>({value:c.id,label:`${c.name} · ${c.inventory}`})))+field('Роль в составе','role','','text',false,null,'Например, накопитель')+field('Дата установки','date',new Date().toISOString().slice(0,10),'date',false)+field('Примечание','note','','text',true,null,''):`<p class="modal-info">Свободных комплектующих нет. Добавьте компонент в реестр перед установкой.</p>`;submit='Установить';}
  if(action==='remove-component'){const comp=db.components.find(c=>c.id===id);title='Снять комплектующую';fields=`<p class="modal-info">${safe(comp?.name||'Компонент')} будет снята с оборудования. Запись об установке останется в истории.</p>${field('Дата снятия','date',new Date().toISOString().slice(0,10),'date',true)}${field('Причина','reason','','text',true,null,'')}`;submit='Снять комплектующую';}
  if(action==='add-component'){title='Добавить комплектующую';fields=field('Название','name','','required',true,null,'Например, модуль памяти Kingston 8 ГБ')+field('Инвентарный номер','inventory','','required')+field('Тип','type','Модуль памяти','required',false,['Модуль памяти','Накопитель','Блок питания','Материнская плата','Трансивер','Другое'])+field('Производитель','maker','')+field('Серийный номер','serial','')+field('МОЛ','mol',roleInfo().id,'required',true,molOpts);submit='Добавить компонент';}
  openModal(title,eyebrow,`<form id="action-form" data-form="${action}" data-id="${id}" data-parent="${asset?.id||''}"><div class="form-grid">${fields}</div>${availableComponentField(action,id)?'':modalFooter(submit)}</form>`);
}
function availableComponentField(action) { return action==='install-component'&&!db.components.some(c=>!c.current); }
function openAuditForm() { const ownerField=isManager()?field('Ответственный','owner',employees[0].name,'required',false,employees.filter(e=>e.role==='МОЛ').map(e=>({value:e.name,label:e.name}))):`<div class="form-field"><label>Ответственный</label><input value="${safe(roleInfo().name)}" disabled><input type="hidden" name="owner" value="${safe(roleInfo().name)}"></div>`; openModal('Новая инвентаризация','Проверка оборудования',`<form id="audit-form" data-form="audit"><div class="form-grid">${field('Название проверки','title','','required',true,null,'Например, инвентаризация серверной')}${field('Квартал','quarter','0','required',false,locations.map((x,i)=>({value:String(i),label:x.quarter})))}${field('Локация','scope','Корпус 12 · кабинет 304','text',false,null,'Корпус, секция или помещение')}${ownerField}${field('Дата начала','date',new Date().toISOString().slice(0,10),'date',false)}${field('Комментарий','comment','','text',true,null,'')}</div>${modalFooter('Создать проверку')}</form>`); }
function createEvent(asset,type,title,detail='',tone='wine') { db.events.unshift({id:`e${Date.now()}`,asset:asset.id,type,title,detail,actor:roleInfo().name,date:'Только что',tone}); }
function handleFormSubmit(form) {
  const data=Object.fromEntries(new FormData(form).entries()); const kind=form.dataset.form; const asset=assetFor(kind==='remove-component'?form.dataset.parent:form.dataset.id);
  if(kind==='asset'){
    if(db.assets.some(a=>a.inventory.trim().toLocaleLowerCase('ru')===data.inventory.trim().toLocaleLowerCase('ru'))){toast('Такой инвентарный номер уже существует');return;}
    const assignment=data.assigned||'';const assigned=assignment.startsWith('employee:')?employees.find(e=>e.id===assignment.slice(9))?.name:assignment.startsWith('location:')?locations[Number(assignment.slice(9))]?.room:'';
    const created={id:`a${Date.now()}`,inventory:data.inventory.trim(),name:data.name.trim(),accounting:data.accounting.trim(),serial:data.serial.trim(),type:data.type,maker:data.maker.trim()||'—',model:data.model.trim()||'—',condition:data.condition,status:data.status,defect:data.defect.trim(),note:data.note.trim(),location:Number(data.location),roomOverride:locations[Number(data.location)].room,assigned:assigned||'—',mol:isManager()?data.mol:roleInfo().id,updated:'Только что',date:new Date().toISOString().slice(0,10)};
    db.assets.unshift(created);createEvent(created,'Поступление','Добавлена карточка оборудования',created.inventory,'green');persist();closeModal();render();toast('Карточка оборудования добавлена');return;
  }
  if(kind==='edit-asset'&&asset){Object.assign(asset,{name:data.name.trim(),accounting:data.accounting.trim(),serial:data.serial.trim(),type:data.type,maker:data.maker.trim()||'—',model:data.model.trim()||'—',note:data.note.trim(),updated:'Только что'});createEvent(asset,'Изменение','Обновлены сведения оборудования',asset.inventory,'blue');persist();closeModal();render();openAsset(asset.id);toast('Изменения сохранены');return;}
  if(kind==='audit'){const loc=locations[Number(data.quarter)];db.audits.unshift({id:`inv-${Date.now()}`,title:data.title,scope:`${loc.quarter} · ${data.scope}`,owner:data.owner,date:fmtDate(data.date),checked:0,total:db.assets.filter(a=>a.location===Number(data.quarter)).length,state:'Запланирована'});persist();closeModal();render();toast('Проверка добавлена в список');return;}
  if(kind==='add-component'){const comp={id:`c${Date.now()}`,inventory:data.inventory.trim(),name:data.name.trim(),type:data.type,maker:data.maker.trim()||'—',serial:data.serial.trim(),parent:null,role:'',installed:'',current:false,mol:data.mol};db.components.unshift(comp);persist();closeModal();render();toast('Комплектующая добавлена');return;}
  if(kind==='install-component'&&asset){const comp=db.components.find(c=>c.id===data.component);if(!comp){toast('Выберите доступную комплектующую');return;}comp.parent=asset.id;comp.role=data.role.trim()||'Компонент';comp.installed=data.date;comp.current=true;createEvent(asset,'Комплектующая','Установлена комплектующая',`${comp.name} · ${comp.role}`,'green');persist();closeModal();render();openAsset(asset.id);toast('Установка сохранена');return;}
  if(kind==='remove-component'){const comp=db.components.find(c=>c.id===form.dataset.id);if(comp){comp.current=false;comp.parent=null;if(asset){createEvent(asset,'Комплектующая','Комплектующая снята',comp.name,'amber');}comp.installed=data.date;persist();closeModal();render();openAsset(asset.id);toast('Установка закрыта, история сохранена');return;}}
  if(kind==='install-free-component'){const comp=db.components.find(c=>c.id===form.dataset.id);const parent=assetFor(data.parent);if(comp&&parent&&canEdit(parent)){comp.current=true;comp.parent=parent.id;comp.role=data.role.trim()||'Компонент';comp.installed=data.date;createEvent(parent,'Комплектующая','Установлена комплектующая',`${comp.name} · ${comp.role}`,'green');persist();closeModal();render();openAsset(parent.id);toast('Установка сохранена');return;}}
  if(['change-status','move-asset','change-mol','retire-asset'].includes(kind)&&asset){
    const before={condition:asset.condition,status:asset.status,location:asset.location,mol:asset.mol};
    if(kind==='change-status'){asset.condition=data.condition;asset.status=data.status;asset.defect=data.defect.trim();createEvent(asset,'Состояние','Изменено состояние оборудования',data.reason||`${data.condition} · ${data.status}`,statusTone(data.condition));}
    if(kind==='move-asset'){asset.location=Number(data.location);asset.roomOverride=data.room;asset.assigned=data.assigned.trim()||'—';createEvent(asset,'Перемещение','Оборудование перемещено',fullLocation(asset),'wine');}
    if(kind==='change-mol'){asset.mol=data.mol;createEvent(asset,'Смена МОЛ','Изменено материально ответственное лицо',`${molFor(before.mol).name} → ${molFor(asset.mol).name}`,'blue');}
    if(kind==='retire-asset'){asset.status='Выведено из эксплуатации';asset.condition=asset.condition==='Неизвестно'?'Неизвестно':asset.condition;asset.updated='Только что';createEvent(asset,'Списание','Оборудование выведено из эксплуатации',data.reason||`Дата ${fmtDate(data.date)}`,'red');}
    asset.updated='Только что';persist();closeModal();closeDetail();render();openAsset(asset.id);toast(kind==='retire-asset'?'Списание зафиксировано':'Изменения сохранены');return;
  }
  if(kind==='employee'){employees.unshift({id:`emp-${Date.now()}`,name:data.name,initials:initialOf(data.name),role:'Сотрудник',department:data.department,position:data.position,active:true,createdBy:roleInfo().id});closeModal();render();toast('Сотрудник добавлен');return;}
  if(kind==='employee-edit'){const person=employees.find(e=>e.id===form.dataset.id);if(person&&(isManager()||person.createdBy===roleInfo().id)){Object.assign(person,{name:data.name,initials:initialOf(data.name),department:data.department,position:data.position});closeModal();render();toast('Сведения о сотруднике обновлены');return;}toast('Можно изменить только созданную вами запись');return;}
  if(kind==='location'){locations.push({quarter:data.quarter,address:data.address,участок:data.участок,building:data.building,section:data.section,room:data.room});closeModal();render();toast('Локация добавлена');return;}
  if(kind==='catalog'){closeModal();render();toast('Значение справочника добавлено');return;}
}

function showAddEmployee(){openModal('Добавить сотрудника','Пользователь оборудования',`<form data-form="employee"><div class="form-grid">${field('ФИО','name','','required',true)}${field('Подразделение','department','ИТ-отдел','required')}${field('Должность','position','','required')}</div>${modalFooter('Добавить сотрудника')}</form>`);}
function showEditEmployee(id){const person=employees.find(e=>e.id===id);if(!person)return;openModal('Изменить сотрудника','Сотрудники',`<form data-form="employee-edit" data-id="${person.id}"><div class="form-grid">${field('ФИО','name',person.name,'required',true)}${field('Подразделение','department',person.department,'required')}${field('Должность','position',person.position,'required')}${field('Материально ответственное лицо','isMol',person.role==='МОЛ'?'Да':'Нет','required',false,['Да','Нет'])}</div>${modalFooter()}</form>`);}
function showAddLocation(){openModal('Добавить локацию','Структура мест',`<form data-form="location"><div class="form-grid">${field('Квартал','quarter','','required',true,null,'Название квартала')}${field('Участок','участок','','required')}${field('Корпус','building','','required')}${field('Секция','section','','required')}${field('Помещение','room','','required')}</div>${modalFooter('Добавить локацию')}</form>`);}
function showAddCatalog(){openModal('Добавить значение','Справочник',`<form data-form="catalog"><div class="form-grid">${field('Название','name','','required',true,null,'Введите значение')}${field('Описание','description','','text',true,null,'')}</div>${modalFooter('Добавить значение')}</form>`);}
function showNotifications(){openModal('Уведомления','События',`<div class="activity-list activity-tight">${db.events.slice(0,4).map(e=>`<div class="activity-item"><span class="activity-icon ${safe(e.tone)}">${icon('bell')}</span><div class="activity-copy"><strong>${safe(e.title)}</strong><span>${safe(e.date)} · ${safe(e.actor)}</span></div></div>`).join('')}</div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal">Закрыть</button></div>`);}
function exportCsv(kind='assets'){const rows=kind==='history'?[['Событие','Оборудование','Дата','Пользователь','Описание'],...db.events.map(e=>[e.title,assetFor(e.asset)?.name||'',e.date,e.actor,e.detail])]:[['Инвентарный номер','Реальное название','Тип','Модель','Производитель','Состояние','Статус использования','Локация','Назначено','МОЛ'],...visibleAssets().map(a=>[a.inventory,a.name,a.type,a.model,a.maker,a.condition,a.status,fullLocation(a),a.assigned,molFor(a.mol).name])];const content='\ufeff'+rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(';')).join('\r\n');const blob=new Blob([content],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=kind==='history'?'журнал-событий.csv':'реестр-оборудования.csv';link.click();URL.revokeObjectURL(url);toast('Файл выгружен');}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`${icon('check')}<span>${safe(message)}</span>`;$('#toast-region').append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3300);}
function closeSidebar(){const sidebar=$('#sidebar'),scrim=$('.sidebar-scrim');sidebar?.classList.remove('open');scrim?.classList.remove('open');}
function toggleSidebar(){const sidebar=$('#sidebar'),scrim=$('.sidebar-scrim');if(!sidebar||!scrim)return;sidebar.classList.toggle('open');scrim.classList.toggle('open');}
function bindDelegation(){
  document.addEventListener('click',event=>{
    const roleButton=event.target.closest('[data-role]'); if(roleButton){setRole(roleButton.dataset.role);return;}
    const viewButton=event.target.closest('[data-view]'); if(viewButton){closeDetail();currentView=viewButton.dataset.view;inventoryQuery='';render();return;}
    const filterType=event.target.closest('[data-filter-type]');if(filterType){filters.type=filterType.dataset.filterType;render();return;}
    const catalog=event.target.closest('[data-catalog-tab]');if(catalog){catalogTab=catalog.dataset.catalogTab;render();return;}
    const actionButton=event.target.closest('[data-action]');if(!actionButton)return;
    const {action,id,value}=actionButton.dataset;
    if(action==='sidebar'){toggleSidebar();return;}
    if(action==='add-asset'){openAddAsset();return;}
    if(action==='inline-type'){const form=actionButton.closest('form'),name=prompt('Название нового типа оборудования');if(name?.trim()){const select=$('select[name="type"]',form),option=new Option(name.trim(),name.trim(),true,true);select.add(option);toast('Тип добавлен в список формы');}return;}
    if(action==='inline-employee'){const form=actionButton.closest('form'),name=prompt('ФИО пользователя оборудования');if(name?.trim()){const person={id:`emp-${Date.now()}`,name:name.trim(),initials:initialOf(name),role:'Сотрудник',department:'ИТ-отдел',position:'Сотрудник',active:true,createdBy:roleInfo().id};employees.push(person);const assignment=$('select[name="assigned"]',form);assignment.add(new Option(`Сотрудник · ${person.name}`,`employee:${person.id}`,true,true));toast('Сотрудник добавлен в список');}return;}
    if(action==='inline-location'){const form=actionButton.closest('form');const vals=['Название квартала','Участок','Корпус','Секция','Помещение'].map(x=>prompt(x));if(vals.every(v=>v?.trim())){const loc={quarter:vals[0].trim(),участок:vals[1].trim(),building:vals[2].trim(),section:vals[3].trim(),room:vals[4].trim()};locations.push(loc);const select=$('select[name="location"]',form);select.add(new Option(`${loc.quarter} · ${loc.участок} · ${loc.building} · ${loc.section} · ${loc.room}`,String(locations.length-1),true,true));toast('Локация добавлена в список формы');}return;}
    if(action==='install-free'){openInstallFreeComponent(db.components.find(c=>c.id===id));return;}
    if(action==='edit-asset'){openEditAsset(id);return;}
    if(action==='open-asset'){openAsset(id);return;}
    if(action==='close-detail'){closeDetail();return;}
    if(action==='close-modal'){closeModal();return;}
    if(action==='change-status'||action==='move-asset'||action==='change-mol'||action==='retire-asset'||action==='install-component'||action==='remove-component'||action==='add-component'){if(action==='add-component')openActionForm(action,'');else openActionForm(action,id);return;}
    if(action==='open-component'){openComponent(id);return;}
    if(action==='new-audit'){openAuditForm();return;}
    if(action==='continue-audit'){toast('Открыт список оборудования для проверки');currentView='equipment';render();return;}
    if(action==='export'){exportCsv();return;}
    if(action==='export-history'){exportCsv('history');return;}
    if(action==='reset-filters'){filters={status:'',type:'',quarter:'',mol:''};inventoryQuery='';render();return;}
    if(action==='notifications'){showNotifications();return;}
    if(action==='switch-role'){setRole(currentRole==='mol'?'manager':'mol');return;}
    if(action==='add-employee'){showAddEmployee();return;}
    if(action==='add-location'){showAddLocation();return;}
    if(action==='add-catalog'){showAddCatalog();return;}
    if(action==='help'){openModal('Поддержка','Контактная информация',`<p class="modal-info">По вопросам доступа и работы с оборудованием обратитесь к администратору системы или руководителю ИТ-отдела.</p><div class="kv-grid"><div class="kv"><label>Подразделение</label><strong>ИТ-отдел</strong></div><div class="kv"><label>Часы работы</label><strong>Рабочее время отеля</strong></div></div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal">Закрыть</button></div>`);return;}
    if(action==='copy-inventory'){navigator.clipboard?.writeText(value).then(()=>toast('Инвентарный номер скопирован')).catch(()=>toast(value));return;}
    if(action==='edit-location'){toast('Выберите поля локации для изменения');return;}
    if(action==='edit-employee'){showEditEmployee(id);return;}
    if(action==='manage-accounts'){openModal('Учетные записи','Доступ к системе',`<div class="table-scroll"><table class="data-table"><thead><tr><th>Пользователь</th><th>Роль</th><th>Статус</th></tr></thead><tbody>${employees.map(p=>`<tr><td>${safe(p.name)}</td><td>МОЛ</td><td>${badge(p.active?'Активен':'Неактивен')}</td></tr>`).join('')}<tr><td>${safe(manager.name)}</td><td>Руководство</td><td>${badge('Активен')}</td></tr></tbody></table></div><div class="form-footer"><button class="btn btn-primary" data-action="close-modal">Закрыть</button></div>`);return;}
    if(action==='edit-catalog'||action==='catalog-rules'){toast('Управление значениями справочника');return;}
    if(action==='download-template'){const template='Участок;Корпус;Секция;Помещение;Тип;Модель;Название по бухгалтерии;Кол-во;Инвентарный номер;S/N;Дефект;Пользователь;МОЛ;Примечание;Актуализация\r\n';const blob=new Blob(['\ufeff'+template],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='шаблон-оборудование.csv';link.click();URL.revokeObjectURL(url);toast('Шаблон выгружен');return;}
    if(action==='import-continue'){openModal('Предварительная проверка','Импорт данных',`<p class="modal-info">Файл выбран. На следующем шаге система сопоставит колонки, проверит дубли инвентарных номеров и покажет ошибки до внесения записей.</p><div class="kv-grid"><div class="kv"><label>Файл</label><strong>${safe($('#upload-filename')?.textContent||'Файл')}</strong></div><div class="kv"><label>Статус</label><strong>Готов к проверке</strong></div></div><div class="form-footer"><button class="btn" data-action="close-modal">Отмена</button><button class="btn btn-primary" data-action="close-modal">Проверить файл</button></div>`);return;}
    if(action==='open-filters'){currentView='equipment';render();return;}
  });
  document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();handleFormSubmit(form);});
  $('#profile-button').addEventListener('click',()=>{const open=$('.role-switch').classList.toggle('open');$('#profile-button').setAttribute('aria-expanded',String(open));});
  document.addEventListener('click',event=>{if(!event.target.closest('#role-switch'))$('.role-switch').classList.remove('open');});
  $('#global-search').addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.value.trim()){inventoryQuery=event.target.value.trim();currentView='equipment';render();}});
  document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('#global-search').focus();}if(event.key==='Escape'){closeModal();closeDetail();closeSidebar();}});
}
bindDelegation();
render();


